tools.example:
model.component("comp1").physics().create("cir", "Circuit", "geom1");
model.component("comp1").physics("cir").create("V1", "VoltageSource", -1);
model.component("comp1").physics("cir").feature("V1").set("Connections", new int[][]{{1}, {0}});
model.component("comp1").physics("cir").feature("V1").set("value", "5[V]");
model.component("comp1").physics("cir").create("R1", "Resistor", -1);
model.component("comp1").physics("cir").feature("R1").set("Connections", new int[][]{{1}, {2}});
model.component("comp1").physics("cir").feature("R1").set("R", "10[ohm]");
model.component("comp1").physics("cir").create("IvsU1", "ModelDeviceIV", -1);
model.component("comp1").physics("cir").feature("IvsU1").set("Connections", new int[][]{{2}, {0}});
model.component("comp1").physics("cir").feature("IvsU1").set("V_src", "root.comp1.ec.V0_1");

model.component("comp1").physics("mf").create("fcal1", "ForceCalculation", 3);
model.component("comp1").physics("mf").feature("fcal1").selection().set(new int[]{4});
model.component("comp1").physics("mf").feature("fcal1").set("ForceName", "rotor");
// Results > Global Evaluation: mf.Forcez_rotor, mf.Tax_rotor

model.component("comp1").physics("mf").create("ibc1", "ImpedanceBoundaryCondition", 2);
model.component("comp1").physics("mf").feature("ibc1").selection().set(new int[]{5, 6, 7});
model.component("comp1").physics("mf").feature("ibc1").set("sigma_mat", "userdef");
model.component("comp1").physics("mf").feature("ibc1").set("sigma", "5.998e7");
// loss: mf.Qsh on the boundary

model.component("comp1").physics("emw").create("port1", "Port", 2);
model.component("comp1").physics("emw").feature("port1").selection().set(new int[]{1});
model.component("comp1").physics("emw").feature("port1").set("PortType", "Rectangular");
model.component("comp1").physics("emw").feature("port1").set("PortExcitation", "on");
model.component("comp1").physics("emw").feature("port1").set("Pin", "1[W]");
model.component("comp1").physics("emw").create("port2", "Port", 2);
model.component("comp1").physics("emw").feature("port2").selection().set(new int[]{6});
model.component("comp1").physics("emw").feature("port2").set("PortType", "Numeric");
// study: Boundary Mode Analysis (port2) then Frequency Domain

model.component("comp1").physics("emw").create("imp1", "Impedance", 2);
model.component("comp1").physics("emw").feature("imp1").selection().set(new int[]{2, 3, 4});
model.component("comp1").physics("emw").feature("imp1").set("sigma_mat", "userdef");
model.component("comp1").physics("emw").feature("imp1").set("sigma", "5.8e7");
// losses: emw.Qsh, Q factor: emw.Qfactor in eigenfrequency studies

model.component("comp1").physics("emw").create("ffd1", "FarFieldDomain", 3);
model.component("comp1").physics("emw").feature("ffd1").selection().set(new int[]{2});
model.component("comp1").physics("emw").feature("ffd1").feature("ffc1").selection().set(new int[]{5, 6, 7, 8, 9, 10});
// Results: 3D Plot Group > Radiation Pattern, expression emw.normdBEfar; Global: emw.gain, emw.D

model.component("comp1").physics("emw").prop("BackgroundField").set("SolveFor", "scatteredField");
model.component("comp1").physics("emw").prop("BackgroundField").set("Eb", new String[]{"0", "0", "E0*exp(-j*emw.k0*x)"});
// Results: relative scattered field emw.relEz, RCS: emw.sigmaRCS / cross sections via emw.Poavx integration
